#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
bash bin/handle POST "/events/1/edit?/save" | grep -q "^200 save" || { echo "legacy"; fail=1; }
bash bin/render event | grep -q "action=\"?action=save\"" || { echo "url"; fail=1; }
exit $fail

# フォームの枠組み
- フォームは自分のページに POST する。どの操作かはクエリで指定する: `?action=<操作名>`（lib/actions.sh の action_url）
- サーバは action_from_query でクエリから操作名を取り出し、app/forms/*.form にある操作だけを受け付ける

 M docs/framework.md
 M lib/actions.sh
 M tests/forms_test.sh

